<section class="checker-organised-report" x-show="!busy && result" aria-label="Job requirements and recommendations">
    <details class="checker-report-disclosure" x-show="result?.assessment?.suggestions?.length"><summary>Suggestions to improve your CV</summary><ul><template x-for="(item, index) in result?.assessment?.suggestions ?? []" :key="index"><li><strong x-text="item.section"></strong><p x-text="item.improvement"></p><p x-text="item.reason"></p></li></template></ul></details>
    <details class="checker-report-disclosure" x-show="(result?.assessment?.recommendations ?? result?.ai_analysis?.recommendations ?? []).length"><summary>Recommendations</summary><ul><template x-for="(tip, index) in result?.assessment?.recommendations ?? result?.ai_analysis?.recommendations ?? []" :key="index"><li x-text="tip"></li></template></ul></details>
    <details class="checker-report-disclosure checker-report-warning" x-show="result?.assessment?.warnings?.length"><summary>Warnings</summary><div class="checker-report-warning-content"><ul><template x-for="(warning, index) in result?.assessment?.warnings ?? []" :key="index"><li><strong x-text="warning.requirement"></strong><p x-text="warning.explanation"></p><p x-text="warning.recommended_action"></p></li></template></ul></div></details>
    <details class="checker-report-disclosure" x-show="result?.assessment?.questions_for_candidate?.length"><summary>Information to confirm</summary><ul><template x-for="(item, index) in result?.assessment?.questions_for_candidate ?? []" :key="index"><li x-text="item"></li></template></ul></details>
    <section class="checker-report-group" x-show="!result?.ai_analysis && result?.suggestions?.length"><h4 class="checker-report-heading">Improve your CV</h4><ul><template x-for="(item, index) in result?.suggestions ?? []" :key="index"><li x-text="item.suggestion"></li></template></ul></section>
</section>
